import { BaseNode, NodeInfo } from './BaseNode';
import { BrainCircuit } from 'lucide-react';

export const LLMNode = ({ id }) => (
  <BaseNode id={id} title="LLM" accentColor="#10b981" Icon={BrainCircuit}
    inputs={[{ id: 'system', label: 'system' }, { id: 'prompt', label: 'prompt' }]}
    outputs={[{ id: 'response', label: 'response' }]}>
    <NodeInfo>Processes a prompt using a large language model and returns a response.</NodeInfo>
  </BaseNode>
);
